}
-------define -----------

---@class UIMailBox
---@field DrawBtn                        UnityEngine.UI.Button
---@field GridView                        SuperScrollView.LoopGridView
---@field TextContent                    UnityEngine.UI.Text
---@field EmptyText                    UnityEngine.UI.Text
---@field StarButton                        UnityEngine.UI.Button
---@field TitleText                        UnityEngine.UI.Text
---@field ListView                        UnityEngine.RectTransform
---@field DeleteBtn                        UnityEngine.UI.Button
