local UIMailBox = Class("UIMailBox")

function UIMailBox:__init()
    self.prizes = {} ---记录服务器的原始数据
    self.emails = {}
    self.selectedIdx = 1
    self.curTab = TabType.MailBox
    self.countdown = nil
    self.__initial = false
end

function UIMailBox:__delete()
    self.controller = nil
    self.emails = nil
    self.selectedIdx = nil
    self.curTab = nil
    self.countdown = nil
    self.__initial = false
end

function UIMailBox:Awake()
    -- KTool.SetActive(self.RightPanel.gameObject, false)
    local animator = self.RightPanel.gameObject:GetComponent(typeof(CS.UnityEngine.Animator))
    if isNotNull(animator) then
        animator.enabled = false
    end
    self.ListView = KTool.GetComponent(self.ListView.gameObject, typeof(LoopListView2))

    self.GridView:InitGridView(0, Bind(self, self.OnGetRewardItemByIndex))

    local topMB = CfUtils.GetLuaScr(self.CommonTopNode.gameObject, CommonTopTabNodePath)
    local function SwitchTabButton()
        ---选中不需的标签页时
        self.curTab = topMB.selectIndex
        self.selectedIdx = 1
        self:FreshMainUI()
    end
    topMB:FillToggles({
        {
            text = localize("邮件"),
            func = SwitchTabButton
        },
        {
            text = localize("收藏"),
            func = SwitchTabButton
        },
    })

    SetButtonAction(self.StarButton, function()
        ---收藏按钮
        local email = self.emails[self.selectedIdx]
        if checkInt(email.hasDrawn) == 0 then
            ---不能收藏
            if checkNumber(email.important) == 1 then
                GameUtils.Toast(localize("请阅后再收藏"))
            else
                GameUtils.Toast(localize("请先领取后再收藏"))
            end
            return
        end
        local prize = self.emails[self.selectedIdx]
        if checkNumber(prize.isFavorite) == 1 then
            return
        end
        local prizeId = prize.prizeId
        GameUtils.Request(Interfaces.PrizeFavorite, { prizeId = prizeId }, function(request, response)
            local code = checkNumber(response.errCode)
            if code == 0 then
                GameUtils.Toast(localize('收藏成功'))
                self.selectedIdx = 1
                prize.isFavorite = 1
                self:FreshMainUI()
            end
        end)
    end)
    SetButtonAction(self.DrawBtn, function()
        --领取按钮的逻辑
        if self.curTab == TabType.MailBox then
            if checkNumber(self.emails[self.selectedIdx].hasDrawn) == 1 then
                ---变成删除操作
                GameUtils.SecondConfirm(localize('是否删除当前的邮件?'), function()
                    local prizeId = self.emails[self.selectedIdx].prizeId
                    GameUtils.Request(Interfaces.PrizeDelete, { prizeId = prizeId }, function(request, response)
                        local code = checkNumber(response.errCode)
                        if code == 0 then
                            self.selectedIdx = 1
                            GameUtils.Request(Interfaces.PrizeEnter, {}, Bind(self, self.RequestEnterSuccess))
                        end
                    end)
                    return true
                end, nil, localize('[删除后不可恢复]'))
            else
                local prize = self.emails[self.selectedIdx]
                local prizeId = prize.prizeId
                GameUtils.Request(Interfaces.PrizeDraw, { prizeId = prizeId }, function(request, response)
                    local code = checkNumber(response.errCode)
                    if code == 0 then
                        prize.hasDrawn = 1
                        prize.expirationTime = math.min(checkNumber(prize.expirationTime), SevenDaysTime - 1)
                        local responseData = checkTable(response.data)
                        if isSet(responseData, "rewards") then
                            if #responseData.rewards > 0 then
                                GoodsUtils.DrawRewards(responseData.rewards, true)
                                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                            else
                                GameUtils.Toast(localize("沒有可领取的物品"))
                            end
                        end
                        self:FreshMainUI()
                    end
                end)
            end
        else
            GameUtils.SecondConfirm(localize('是否删除当前的邮件?'), function()
                local prizeId = self.emails[self.selectedIdx].prizeId
                GameUtils.Request(Interfaces.PrizeDelete, { prizeId = prizeId }, function(request, response)
                    local code = checkNumber(response.errCode)
                    if code == 0 then
                        self.selectedIdx = 1
                        GameUtils.Request(Interfaces.PrizeEnter, {}, Bind(self, self.RequestEnterSuccess))
                    end
                end)
                return true
            end, nil, localize('[删除后不可恢复]'))
        end
    end)
    SetButtonAction(self.DrawAllBtn, function()
        --领取全部
        if self.emails and #self.emails > 0 then
            GameUtils.Request(Interfaces.PrizeDraw, {}, function(request, response)
                local code = checkNumber(response.errCode)
                if code == 0 then
                    local responseData = checkTable(response.data)
                    -- 没有可以领取的道具 --是否提示
                    if isSet(responseData, "rewards") then
                        if #responseData.rewards > 0 then
                            GoodsUtils.DrawRewards(responseData.rewards, true)
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                        else
                            GameUtils.Toast(localize("沒有可领取的物品"))
                        end

                    end
                    GameUtils.Request(Interfaces.PrizeEnter, {}, Bind(self, self.RequestEnterSuccess))
                end
            end)
        else
            GameUtils.Toast(localize("暂无邮件"))
        end

    end)
    SetButtonAction(self.DeleteBtn, function()
        --删除已读
        if self.emails and #self.emails > 0 then
            GameUtils.SecondConfirm(localize('是否删除所有的已读邮件?'), function()
                GameUtils.Request(Interfaces.PrizeDelete, {}, function(request, response)
                    local code = checkNumber(response.errCode)
                    if code == 0 then
                        self.selectedIdx = 1
                        GameUtils.Request(Interfaces.PrizeEnter, {}, Bind(self, self.RequestEnterSuccess))
                    end
                end)
                return true
            end, nil, localize('[删除后不可恢复]'))
        else
            GameUtils.Toast(localize("暂无邮件"))
        end

    end)
end

---OnGetItemByIndex
---邮箱列表cell生成函数
---@param listView SuperScrollView.LoopListView2
---@param index number 位置
function UIMailBox:OnGetItemByIndex(listView, index)
    --因为lua层的数据源是从1开始
    local position = index + 1
    if position < 1 or position > #self.emails then
        return nil
    end
    local email = self.emails[position]
    if isNull(email) then
        return nil
    end
    local cell = listView:NewListViewItem(PrefabName)
    ---@type Engine.Modules.LuaBehaviour
    local mailCell = GetLuaBehaviour(cell.gameObject, UIMailCellPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        mailCell:Init()
    end
    if not KTool.IsNull(mailCell) and not KTool.IsNull(mailCell.Env) then
        ---@type UIMailCell
        local env = mailCell.Env
        env:SetClickCB(function(index)
            CriWareUtils.PlaySe(uiSheets.UI_Menu.path, uiSheets.UI_Menu.ui_mail_change)
            if index == self.selectedIdx then
                return
            end
            ---清除之前的位置状态
            if #self.emails <= 0 then
                return
            end
            self.selectedIdx = index
            self:FreshMainUI()
        end)
        env:FreshCell(email, position, self.curTab == TabType.MyMail)
        env:SetSelected(checkNumber(self.selectedIdx) == position)
    end
    return cell
end

---FreshListView
---刷新列表listview数据
function UIMailBox:FreshListView()
    local t = {}
    if self.curTab == TabType.MailBox then
        ---当前的未收藏的邮件
        for i, v in pairs(self.prizes) do
            if checkInt(v.isFavorite) == 0 then
                table.insert(t, v)
            end
        end
    else
        ---当前的已收藏的邮件
        for i, v in pairs(self.prizes) do
            if checkInt(v.isFavorite) == 1 then
                table.insert(t, v)
            end
        end
    end
    self.emails = t
    if not self.__initial then
        self.__initial = true
        --列表
        self.ListView:InitListView(#self.emails, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ListView, #self.emails, false)
    end
end

function UIMailBox:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.firstInit = true
        --请求数据
        GameUtils.Request(Interfaces.PrizeEnter, {}, Bind(self, self.RequestEnterSuccess))
        --请求结束后
        coroutine.yield(Yielders.EndOfFrame)
        ----然后添加计时器
        ---@type Engine.Modules.CDTimerModule
        local cdTimerModule = CDTimerModule.GetInstance()
        if not isNull(self.countdown) then
            cdTimerModule:RemoveCD(self.countdown)
            self.countdown = nil
        end
        self.countdown = cdTimerModule:AddCD(1, function(count, id)
            if table.length(self.emails) > 0 then
                for _, email in pairs(self.emails) do
                    if isTable(email) then
                        email.expirationTime = math.max(checkNumber(email.expirationTime) - 1, 0)
                    end
                end
                --发送事件
                Events.Broadcast(Constants.EventNames.UIMailCountDownEventName)
            end
        end, CountDownTime, false, true)
    end))
    return coWait
end

---RequestEnterSuccess
---请求邮箱Prize/Enter接口后的回调函数
---@param request Engine.Http.HttpRequest
---@param response table 返回的json数据
function UIMailBox:RequestEnterSuccess(request, response)
    local code = checkNumber(response.errCode)
    if code == 0 then
        local responseData = checkTable(response.data)
        if isSet(responseData, "prizes") then
            self.prizes = checkTable(responseData.prizes)
            --先排序邮件
            --self:SortEmail()
            -- 刷新列表相关的逻辑
            self:FreshMainUI()
        end
    end
end

---SortEmail
---对返回的邮箱数据进行排序
---
function UIMailBox:SortEmail()
    if table.length(self.prizes) > 0 then
        table.sort(self.prizes, function(a, b)
            if checkNumber(a.hasDrawn) ~= checkNumber(b.hasDrawn) then
                return checkNumber(a.hasDrawn) < checkNumber(b.hasDrawn)
            else
                return checkString(a.effectTime) > checkString(b.effectTime)
            end
        end)
    end
end

---OnGetRewardItemByIndex
---奖励数据处理
---@param gridView SuperScrollView.LoopGridView
---@param index number
---@param row number
---@param column number
function UIMailBox:OnGetRewardItemByIndex(gridView, index, row, column)
    if index < 0 then
        return nil
    end
    local cell = gridView:NewListViewItem(RewardPrefabName)
    local goodNode = cell.transform:Find("GoodNode")
    local reScale = goodNode.gameObject:GetComponent(typeof(ReverseScale))
    reScale:ResetScale()
    local email = self.emails[self.selectedIdx]
    local position = index + 1
    if email and position <= table.count(email.reward) then
        local reward = email.reward[position]
        local getIcon = cell.transform:Find("GetImage")
        if not isNull(getIcon) then
            KTool.SetActive(getIcon.gameObject, checkInt(email.hasDrawn) == 1)
        end
        local goodItemNodeMB = GetLuaBehaviour(goodNode.gameObject, GoodNodeMBPath)
        if not isNull(goodItemNodeMB) then
            if isNull(goodItemNodeMB.Env) then
                goodItemNodeMB:Init()
            end
            ---@type GoodNodeMB
            local goodItemNodeEnv = goodItemNodeMB.Env
            goodItemNodeEnv:Reload({
                goodsId = reward.goodsId, isShowNo = true, text = 'x' .. FormatCurrencyNum(reward.num)
            })
            goodItemNodeEnv:SetClickButtonAction(function(goodsId)
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                if isTable(vo) then
                    GameUtils.ShowCommonTipsBoard(goodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
                end
            end)
            goodItemNodeEnv:SetSanXingGainShow(checkNumber(self.emails[self.selectedIdx].hasDrawn) == 1)
        end
    end
    return cell
end

---ShowCellDetail
---显示某个格子的具体信息细节
---@param cellIndex number
function UIMailBox:ShowCellDetail(cellIndex)
    if cellIndex >= 1 and cellIndex <= table.count(self.emails) then
        local email = self.emails[cellIndex]
        if isTable(email) then
            if self.firstInit then
                self.firstInit = false
                local animator = self.RightPanel.gameObject:GetComponent(typeof(CS.UnityEngine.Animator))
                if isNotNull(animator) then
                    animator.enabled = true
                end
            end
            --self.TitleText.text = email.title
            local content = email.content
            if not string.isEmpty(content) and string.find(content, "$accessToken") then
                ---@type SDKService
                local SDKService = import('Game.Entry.SDKService')
                if SDKService:GetInstance():IsCommonSDK() then
                    ---@type UserComponent
                    local userComponent =  GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
                    if  isNotNull(userComponent) then
                        content = string.gsub(content, "{$accessToken}", userComponent.userInfo.access_token)
                    end
                else
                    content = string.gsub(content, "{$accessToken}", "")
                end
            end
            self.TextContent.text = content
            --local d = date(checkNumber(email.effectTime)):tolocal()
            --self.TxtTime.text = d:fmt("%Y-%m-%d")
            CfUtils.SetUISwitchText(self.TitleText, checkNumber(email.important) == 1 and 2 or 1)
            CfUtils.SetUISwitchText(self.TxtTime, checkNumber(email.important) == 1 and 2 or 1)
            CfUtils.SetUISwitchText(self.TextContent, checkNumber(email.important) == 1 and 2 or 1)
            CfUtils.SetActive(self.StarButton.transform.parent:Find("Normal"), checkNumber(email.important) ~= 1)
            CfUtils.SetActive(self.StarButton.transform.parent:Find("Important"), checkNumber(email.important) == 1)
            if checkNumber(email.isFavorite) == 1 then
                CfUtils.SetUISwitchImage(self.StarButton, 2)
            else
                CfUtils.SetUISwitchImage(self.StarButton, checkNumber(email.important) == 1 and 3 or 1)
            end
            if isSet(email, "reward") and isTable(email.reward) and table.count(email.reward) > 0 then
                --if self.curTab == TabType.MailBox then
                KTool.SetActive(self.GridView.gameObject, true)
                ---@type Game.Native.Common.FontStyleButton
                local fontStyleButton = KTool.GetComponent(self.DrawBtn.gameObject, typeof(CS.Game.Native.Common.FontStyleButton))
                CfUtils.SetActive(self.DrawBtn.transform.parent:Find("redPoint"), checkNumber(email.hasDrawn) == 0 and checkNumber(email.important) == 1)
                if checkInt(email.hasDrawn) == 1 then
                    fontStyleButton:ResetFontStyle('B7', localize('删除'))
                else
                    if checkNumber(email.important) == 1 then
                        fontStyleButton:ResetFontStyle('B6', localize('我已阅'))
                    else
                        fontStyleButton:ResetFontStyle('B6', localize('领取'))
                    end
                end
                --刷新右侧资历列表的数据
                local length = table.length(email.reward)
                GameUtils.ReloadData(self.GridView, length)
                self.GridView.ScrollRect.horizontal = length > 4
            else
                ---邮件没有奖励
                KTool.SetActive(self.GridView.gameObject, false)
                KTool.SetActive(self.DrawBtn.gameObject, false)
            end
        end
    end
end

--获取没有领取的邮件数量
function UIMailBox:GetNoDrawnNum()
    local num = 0
    if not self.prizes and #self.prizes == 0 then
        return num
    end

    for k, v in pairs(self.prizes) do
        if v.hasDrawn == 0 then
            --num = num + 1
            return 1
        end
    end
    return num
end

---FreshMainUI
---用来刷新整体邮箱界面
---是否存在邮件无时显示无的背景
function UIMailBox:FreshMainUI()
    self:FreshListView()
    ---没有数据显示为不存在数据的逻辑
    if self.curTab == TabType.MailBox then
        --KTool.SetActive(self.StarButton.gameObject, true)
        KTool.SetActive(self.ButtonGroup.gameObject, true)
        if table.length(self.emails) > 0 then
            KTool.SetActive(self.GridView.gameObject, true)
            KTool.SetActive(self.DrawBtn.gameObject, true)
            --KTool.SetActive(self.DeleteFavoriteBtn.gameObject, false)
            KTool.SetActive(self.DrawAllBtn.gameObject, true)
            KTool.SetActive(self.DeleteBtn.gameObject, true)
            KTool.SetActive(self.EmptyNode.gameObject, false)
            KTool.SetActive(self.RightPanel.gameObject, true)
            ---改listview大小
            ---@type UnityEngine.RectTransform
            local rectTransform = KTool.GetComponent(self.ListView.gameObject, typeof(CS.UnityEngine.RectTransform))
            local parentTransform = KTool.GetComponent(self.ListView.transform.parent.gameObject, typeof(CS.UnityEngine.RectTransform))
            rectTransform:SetInsetAndSizeFromParentEdge(CS.UnityEngine.RectTransform.Edge.Top, 0, parentTransform.rect.height - 130)
        else
            self.EmptyText.text = localize('暂无邮件')
            KTool.SetActive(self.EmptyNode.gameObject, true)
            --KTool.SetActive(self.StarNode.gameObject, false)
            KTool.SetActive(self.RightPanel.gameObject, false)
        end
    else
        --KTool.SetActive(self.StarButton.gameObject, false)
        KTool.SetActive(self.ButtonGroup.gameObject, false)
        if table.length(self.emails) > 0 then
            KTool.SetActive(self.GridView.gameObject, true)
            KTool.SetActive(self.DrawBtn.gameObject, true)
            ---更新图片
            KTool.SetActive(self.EmptyNode.gameObject, false)
            KTool.SetActive(self.RightPanel.gameObject, true)
            ---@type UnityEngine.RectTransform
            local rectTransform = KTool.GetComponent(self.ListView.gameObject, typeof(CS.UnityEngine.RectTransform))
            local parentTransform = KTool.GetComponent(self.ListView.transform.parent.gameObject, typeof(CS.UnityEngine.RectTransform))
            rectTransform:SetInsetAndSizeFromParentEdge(CS.UnityEngine.RectTransform.Edge.Top, 0, parentTransform.rect.height)
        else
            self.EmptyText.text = localize('暂无收藏')
            KTool.SetActive(self.EmptyNode.gameObject, true)
            --KTool.SetActive(self.StarNode.gameObject, true)
            KTool.SetActive(self.RightPanel.gameObject, false)
        end
    end

    if self.selectedIdx > 0 then
        self:ShowCellDetail(self.selectedIdx)
    end
end

function UIMailBox:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---停倒计时
        ---@type Engine.Modules.CDTimerModule
        local cdTimerModule = CDTimerModule.GetInstance()
        if not isNull(self.countdown) then
            cdTimerModule:RemoveCD(self.countdown)
            self.countdown = nil
        end
        GameUtils.SetRedPointNum(Constants.RedPointConst.Mail, self:GetNoDrawnNum())
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIMailBox